import {precisionInputAttributes} from './number-display.js';
// Presentation only. The diagnostic receives the actual modeled annual path;
// it never creates a starting invested-capital balance from sales/capital.
const finite=Number.isFinite;
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const scientific=v=>v.toExponential(2).replace(/\.?0+(?=e)/,'');
const num=(v,d=2)=>!finite(v)?'—':v!==0&&(Math.abs(v)<10**-d||Math.abs(v)>=1e9)?scientific(v):v.toLocaleString('en-US',{maximumFractionDigits:Math.min(2,d)});
// Percent conversion can overflow even when the modeled decimal is finite.
const percentNumber=v=>{if(!finite(v))return '—';const scaled=v*100;if(finite(scaled))return num(scaled,1);const [mantissa,exponent]=scientific(v).split('e');return mantissa+'e+'+(Number(exponent)+2);};
const pct=v=>finite(v)?percentNumber(v)+'%':'—';
const ratio=v=>finite(v)&&v>0?num(v,3)+'×':'—';
const year=v=>Number.isInteger(v)?String(v):'—';
export function capitalPathModeDescription(draft){
 const p=draft.capitalPath,a=draft.assumptions||{},profile=draft.operatingProfile;
 if(p?.enabled===true)return `Early efficiency applies through year ${year(p.earlyEndYear)}. The separately authored later ratio begins in year ${Number.isInteger(p.earlyEndYear)?p.earlyEndYear+1:'—'} and holds through year ${year(p.fadeStartYear)}. Capital intensity then fades to terminal-consistent efficiency by year ${year(p.terminalYear)}. Growth and margin keep their own calendars.`;
 if(profile?.id==='aaoi-capacity-ramp-v1')return 'Existing staged capital path: initial sales / capital doubles by years 6–7, then capital intensity fades to the terminal-consistent endpoint. There is no separately authored later ratio.';
 if(profile?.id==='flexible-growth-v1')return `Existing capital-intensity fade: the initial ratio holds through year ${year(profile.schemaVersion===2?profile.capitalHoldYears:profile.explicitYears)}, then intensity fades to the terminal-consistent endpoint in year ${year(profile.schemaVersion===2?profile.capitalMaturityYears:a.years)}. There is no separately authored later ratio.`;
 return 'Existing constant-ratio path: incremental sales / capital stays at the initial assumption throughout the explicit forecast. Terminal reinvestment uses the separate mature marginal ROIC assumption. There is no separately authored later ratio.';
}
export function capitalPhaseControlsHTML(prefix,path,{description=''}={}){
 const text=key=>esc(path?.inputText?.[key]??(finite(path?.[key])?String(path[key]):''));
 const timings=[['earlyEndYear','Early phase ends after year'],['fadeStartYear','Later phase holds through year'],['terminalYear','Terminal efficiency reached in year']];
 return `<section class="capital-phase-controls" aria-label="Optional capital efficiency phases"><label for="${prefix}-capital-mode">Capital efficiency path</label><select id="${prefix}-capital-mode" aria-describedby="${prefix}-capital-help"><option value="existing" ${path?.enabled?'':'selected'}>Keep existing capital path</option><option value="phased" ${path?.enabled?'selected':''}>Set early and later efficiency</option></select><p id="${prefix}-capital-help" class="micro">${esc(description)}</p>${path?.enabled?`<fieldset class="annual-growth-group"><legend>Your later capital efficiency</legend><article class="driver-card"><div class="driver-top"><label for="${prefix}-capital-laterSalesCapital">Later incremental sales / capital<span class="assumption-tag">Your assumption</span></label><div class="driver-number"><input id="${prefix}-capital-laterSalesCapital" data-capital-control="laterSalesCapital" data-capital-prefix="${prefix}" type="text" inputmode="decimal" ${precisionInputAttributes(path?.laterSalesCapital,1,path?.inputText?.laterSalesCapital)} aria-describedby="${prefix}-capital-method ${prefix}-capital-status"><span>×</span></div></div><p class="driver-help">Extra annual revenue per unit of net new capital during the later phase. A higher ratio means less required investment.</p></article><div class="operating-timing-controls"><div class="operating-timing-inputs">${timings.map(([key,label])=>`<div><label for="${prefix}-capital-${key}">${label}</label><input id="${prefix}-capital-${key}" data-capital-control="${key}" data-capital-prefix="${prefix}" type="text" inputmode="numeric" ${precisionInputAttributes(path?.[key],1,path?.inputText?.[key])} aria-describedby="${prefix}-capital-method ${prefix}-capital-status"></div>`).join('')}</div></div><details class="timing-method"><summary>How these phases work</summary><p id="${prefix}-capital-method" class="micro">The early ratio is the assumption above. The later ratio takes effect immediately after the early phase, then stays fixed until the terminal fade begins. Timing must satisfy 1 ≤ early end &lt; later end &lt; terminal year ≤ 30. The fade interpolates capital intensity (1 ÷ sales / capital), not the ratio itself. In simulation, both authored ratios move proportionally with the same sales / capital draw. Turning this option off restores the existing capital path and keeps these phase inputs available.</p></details></fieldset>`:''}<p id="${prefix}-capital-status" class="micro" role="status"></p></section>`;
}
export function capitalEfficiencyPanelHTML(diagnostic,{prefix='guided',ticker='',currency='',earlySalesCapital,capitalPath,forecastRows=[],error=''}={}){
 const title='Implied capital returns';
 if(error||!diagnostic?.rows?.length)return `<h3>${title}</h3><p class="micro">Capital diagnostics are unavailable until the model inputs are valid.${error?' '+esc(error):''}</p>`;
 const rows=diagnostic.rows,first=rows[0],last=rows.at(-1),later=capitalPath?.enabled?rows.find(r=>r.year===capitalPath.earlyEndYear+1):null;
 const netInvestment=forecastRows.reduce((sum,row)=>sum+row.reinvestment,0),amount=v=>num(v,1)+'m '+esc(currency);
 const tableRows=rows.map((row,i)=>`<tr><th scope="row">${esc(row.year)}</th><td>${ratio(row.salesCapital)}</td><td>${amount(forecastRows[i]?.reinvestment)}</td><td>${pct(row.marginalReturnProxy)}</td><td>${finite(row.proxySpread)?(row.proxySpread>0?'+':'')+percentNumber(row.proxySpread)+' pp':'—'}</td></tr>`).join('');
 return `<h3>${title}</h3><div class="economic-insight"><p>Early sales / capital: <b>${ratio(earlySalesCapital)}</b>. ${capitalPath?.enabled?`Later sales / capital: <b>${ratio(capitalPath.laterSalesCapital)}</b>.`:'Later ratio: follows the existing path; no separate later assumption.'}</p><p>Implied forecast net investment: <b>${amount(netInvestment)}</b> over ${rows.length} years.</p><p>Marginal after-tax return proxy: <b>${pct(first.marginalReturnProxy)}</b> in year ${first.year}${later?`; <b>${pct(later.marginalReturnProxy)}</b> at the later phase’s start in year ${later.year}`:''}; <b>${pct(last.marginalReturnProxy)}</b> in year ${last.year}.</p></div><p class="micro">This live diagnostic is a marginal after-tax return proxy: modeled NOPAT ÷ revenue × that year’s incremental sales / capital. A changing margin also reprices existing sales, so this is not ΔNOPAT ÷ net investment. Whole-business ROIC is unavailable without a sourced starting invested-capital balance. No balance is inferred from sales / capital.</p><details id="${prefix}-capital-annual-detail"><summary>Annual efficiency, net investment & return proxy</summary><p class="micro">Net investment funds positive incremental revenue; shrinking revenue releases no capital in this model. The proxy uses actual modeled cash taxes, with no automatic tax credit on losses. Spread compares this proxy with that year’s WACC; it is not an investment return.</p><div class="table-wrap"><table class="workspace-table"><caption><span class="sr-only">${esc(ticker)} · Annual capital efficiency and marginal after-tax return proxy</span></caption><thead><tr><th scope="col">Year</th><th scope="col">Sales / capital</th><th scope="col">Net investment</th><th scope="col">Marginal after-tax return proxy</th><th scope="col">Proxy less WACC</th></tr></thead><tbody>${tableRows}</tbody></table></div><p class="micro">The terminal-consistent endpoint reflects the model’s one-year reinvestment timing. Its proxy can differ from the separately selected mature marginal ROIC; the two are not interchangeable.</p></details>`;
}
